#!/usr/bin/env node
'use strict';

const fs = require('fs');

const PT_LOAD = 1;

function extractMemoryValues(buf) {
  // ELF magic check
  if (buf.length < 20 || buf.readUInt32LE(0) !== 0x464c457f) {
    throw new Error('Not an ELF file');
  }
  const is64 = buf[4] === 2; // EI_CLASS: 1 = 32-bit, 2 = 64-bit
  if (buf[5] !== 1) {
    throw new Error('Only little-endian ELF binaries are supported');
  }

  let e_phoff, e_phentsize, e_phnum;
  if (is64) {
    e_phoff = Number(buf.readBigUInt64LE(0x20));
    e_phentsize = buf.readUInt16LE(0x36);
    e_phnum = buf.readUInt16LE(0x38);
  } else {
    e_phoff = buf.readUInt32LE(0x1c);
    e_phentsize = buf.readUInt16LE(0x2a);
    e_phnum = buf.readUInt16LE(0x2c);
  }

  // Map: virtual address -> 32-bit little-endian value.
  // Later (overlapping) segments win, mirroring how the loader maps memory.
  const memory = new Map();

  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    let p_type, p_offset, p_vaddr, p_filesz, p_memsz;
    if (is64) {
      p_type = buf.readUInt32LE(off + 0);
      p_offset = Number(buf.readBigUInt64LE(off + 8));
      p_vaddr = Number(buf.readBigUInt64LE(off + 16));
      p_filesz = Number(buf.readBigUInt64LE(off + 32));
      p_memsz = Number(buf.readBigUInt64LE(off + 40));
    } else {
      p_type = buf.readUInt32LE(off + 0);
      p_offset = buf.readUInt32LE(off + 4);
      p_vaddr = buf.readUInt32LE(off + 8);
      p_filesz = buf.readUInt32LE(off + 16);
      p_memsz = buf.readUInt32LE(off + 20);
    }
    if (p_type !== PT_LOAD) continue;

    // Every 4-byte window whose start address falls inside the segment's
    // memory range. Bytes beyond p_filesz (BSS, zero padding) read as 0.
    for (let v = p_vaddr; v < p_vaddr + p_memsz; v += 4) {
      let val = 0;
      for (let j = 0; j < 4; j++) {
        const rel = (v - p_vaddr) + j;
        const b = rel < p_filesz ? buf[p_offset + rel] : 0;
        val |= b << (8 * j);
      }
      memory.set(v, val);
    }
  }

  const out = {};
  for (const [addr, val] of memory) out[String(addr)] = val;
  return out;
}

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-file>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);
  const memory = extractMemoryValues(buf);
  process.stdout.write(JSON.stringify(memory) + '\n');
}

main();

